-- PRIVACY POLICY 1.9: ONE SENTENCE SAYS WE MEASURE WHETHER AN INVITATION EMAIL IS OPENED.
--
-- Seat: ceo (the legal texts), for marketing. 3 Nov 2026. The founder asked to know when a supplier opens the invitation
-- (an_invitation_open_is_measured_on_a_tracked_share_and_reaches_the_ceo.sql). Section 9 ("Invitations to businesses") gains
-- one sentence saying that some invitations carry a tiny image served from our own website and what is recorded when it
-- loads (the time, the email program's description, a one-way coded form of the network address, never the address).
-- The other edits are the version label and the change notice; scripts/lib/privacy_1_9.mjs lists them, and undoing them
-- gives 1.8 byte for byte (the registry body below without them hashes to b16a707f..., the live 1.8 row).
-- GENERATED from src/content/legal.json by the registry rule of the_signed_legal_registry_follows_the_14_september_texts.sql
-- (the English page's <div class="body"> content).
--
-- NOBODY SIGNS AGAIN: the privacy policy is not accepted by anyone (the_founders_mobile_leaves_the_current_legal_texts.sql
-- section 2: "Nobody signs these two, so there is no acceptance"), so 1.9 asks no customer or supplier for anything.
--
-- WHAT THIS CHANGES
--   1. the live 1.8 row is copied to privacy-v1.8 (category archived, source archived:privacy), byte-identical, only if 1.8 is
--      still the live version; a re-run inserts nothing.
--   2. the privacy row becomes 1.9 with the body below. The update names the version it supersedes, so a re-run changes nothing.
-- No begin/commit: the applier runs the file as one transaction. Ends with a verdict row.

insert into public.legal_documents (slug, title, category, version, effective_date, summary, body_html, updated_at, content_sha256, source)
select d.slug || '-v' || d.version, d.title, 'archived', d.version, d.effective_date, d.summary, d.body_html, now(),
       encode(sha256(convert_to(d.body_html, 'UTF8')), 'hex'), 'archived:' || d.slug
  from public.legal_documents d
 where d.slug = 'privacy' and d.version = '1.8'
on conflict (slug) do nothing;

update public.legal_documents set body_html = $qd_privacy$<h1>Privacy Policy</h1><div class="muted">How QuotesDone Technologies collects, uses, shares and protects personal data on the QuotesDone anonymous quotation marketplace, and your rights under UAE Federal Decree-Law No. 45 of 2021 (the Personal Data Protection Law).</div><div class="card"><p><strong>What changed in version 1.9 (3 November 2026):</strong> one sentence in section 9 (Invitations to businesses) says that we measure whether our invitation emails are opened, and how. Nothing else in this policy has changed from version 1.8 (2 November 2026).</p></div><div class="card"><h2>1. Who We Are (Data Controller)</h2><p>This Privacy Policy explains how we handle your personal data when you use QuotesDone, an online B2B anonymous quotation marketplace.</p><p>The data controller is:</p><ul><li>QuotesDone Technologies, a Dubai Sole Establishment</li><li>DET Dubai Trader License No. 1633275</li><li>Owner: Ahmad Mhd Nabil Alzain</li><li>Address: Dubai, United Arab Emirates</li><li>Email: management@quotesdone.com; Phone: +971 56 791 8605; WhatsApp: +1 218 316 6814</li></ul><p>We process personal data in accordance with the UAE Personal Data Protection Law, Federal Decree-Law No. 45 of 2021 (PDPL), and its implementing regime overseen by the UAE Data Office, which from June 2026 operates within the new UAE Federal Authority for Artificial Intelligence and Data. This policy applies to customers, suppliers and visitors. Where you act on behalf of a business, references to your personal data mean the personal data of the individuals concerned.</p><h2>2. Personal Data We Collect</h2><p>Depending on how you use the platform, we collect:</p><ul><li>Customer identity and contact data: your name, email address and mobile number, with the mobile number verified by one-time password (OTP).</li><li>Request content: the job or request you submit as text, voice recordings, photographs or drawings, including any personal data you choose to include.</li><li>Supplier data: business details and Know Your Customer (KYC) documents provided for vetting and onboarding.</li><li>Payment data: a payment reference returned by our payment processor, Stripe. We do not store full card numbers; card and Apple Pay details are handled by Stripe, which is certified to the Payment Card Industry Data Security Standard (PCI DSS).</li><li>Usage and technical data: logs, device and connection information, and records of platform activity.</li></ul><p>We do not intentionally collect special categories of data. Please avoid including sensitive details in request content unless necessary.</p><h2>3. Purposes and Lawful Bases</h2><p>We process personal data for clear purposes, each supported by a lawful basis under the PDPL:</p><ul><li>To create and manage your account, verify your mobile by OTP, and provide the marketplace, including matching requests to suppliers and enabling paid reveals (performance of a contract).</li><li>To calculate and collect the customer Reveal Fee of 3% of the quoted value at the point you choose to reveal a supplier, and to keep accounting records (performance of a contract and legal obligation). Suppliers pay no commission or success fee on jobs they win.</li><li>To vet suppliers and verify their KYC documents (performance of the Supplier Agreement, which the supplier asks us to enter into), and to prevent fraud and misuse and secure the platform (compliance with our legal obligations, and the establishment, exercise or defence of legal claims).</li><li>To share a chosen supplier&#x27;s contact details on a paid reveal, and for optional marketing (your consent, which you may withdraw at any time).</li></ul><p>The PDPL does not provide a general "legitimate interests" ground, and we do not rely on one. Where we process personal data without your consent, we rely only on the cases Article 4 of the PDPL permits, as listed above.</p><h2>4. Smart and Automated Processing</h2><p>QuotesDone uses smart and automated tools to operate the marketplace. These tools:</p><ul><li>Structure and standardise the requests you submit (including converting voice, photos and drawings into a structured brief).</li><li>Match each request to suppliers in the matching trade who are likely to be able to quote.</li><li>Summarise requests and quotes to make them easier to compare.</li></ul><p>Some decisions on the platform are made by automated systems, including software that uses large language models, without a person reviewing each case. They include matching and ranking suppliers, checking quotes against your specifications, and assessing refund requests and disputes under our published rules. You remain free to accept, reject or ignore any quote. These decisions are part of the service you contract for, and you agree to them when you accept our Terms of Service (clause 10) or the Supplier Agreement (clause 27). Under Article 18(2)(a) and (c) of the Personal Data Protection Law, the right to object to a decision resulting from automated processing does not apply where the automated processing is agreed in the contract between you and QuotesDone, or where you have given your prior consent to it. You may still object to, or complain about, any decision through the Platform or at management@quotesdone.com: QuotesDone Customer Support handles it and, if it is not resolved there, refers it to the QuotesDone operations team. Automated outputs, including summaries and comparisons, can contain errors; please check the supplier&#x27;s own quotation before relying on it.</p><h2>5. How We Share Data</h2><p>Anonymity is central to QuotesDone. We share personal data only as follows:</p><ul><li>Request content is shared with matched suppliers WITHOUT revealing your identity, so suppliers can prepare anonymised quotes.</li><li>Your contact details are disclosed to a single supplier only after you pay the Reveal Fee and consent to the reveal for that chosen supplier; suppliers receive customer contact data only for jobs revealed to them.</li><li>Our payment processor, Stripe, receives the data needed to take payment (card or Apple Pay) and returns a payment reference.</li><li>Service providers process data on our behalf, under their terms and our instructions. They are named in section 6, with what they process and where.</li></ul><p>We may also disclose data where required by UAE law, a court of competent authority, or to protect our legal rights. We do not sell personal data.</p><h2>6. Service Providers and Cross-Border Transfers</h2><p>Our platform is hosted outside the United Arab Emirates, and our service providers process personal data outside the UAE. They are:</p><ul><li>Supabase (database, file storage, sign-in and server functions): all platform data. Hosted in Singapore.</li><li>Vercel (website hosting and delivery): website requests and technical data.</li><li>OpenRouter and the model providers it routes to (such as Google and Anthropic): the text of requests, documents, quotes and messages that our automated tools read.</li><li>Resend (email delivery) and Microsoft 365 (our company mailbox): email addresses and the content of emails we send and receive.</li><li>Meta (WhatsApp Business Platform) and Twilio (text messages and verification codes): mobile numbers and message content.</li><li>Stripe (payments): the data needed to take a payment.</li><li>Dropbox (backup copies of records and documents): copies of platform records.</li><li>Serper (web search): search queries about businesses, products and prices; these do not include your contact details.</li></ul><p>Except where a location is stated above, these providers process data in the United States and in other countries where they operate. Where we transfer personal data outside the UAE, we apply the safeguards required by Articles 22 and 23 of the PDPL:</p><ul><li>We transfer data to countries the UAE Data Office recognises as providing an adequate level of protection; or</li><li>Where adequacy is not established, we rely on appropriate safeguards such as contractual terms obliging the recipient to protect the data, or on the other grounds those Articles allow, including your explicit consent, in each case in a manner that does not conflict with the public and security interests of the State.</li></ul><p>We keep a register of each provider&#39;s data processing terms and the safeguard it relies on for transfers. You may contact us for more information about the safeguards applied to a transfer.</p><h2>7. Data Retention</h2><p>We keep personal data only for as long as necessary for the purposes described above and to meet legal obligations. Article 3 of Cabinet Decision No. 74 of 2023 (the Executive Regulation of the Tax Procedures Law) requires records to be kept for five years from the end of the calendar year in which they were created. Records that have no tax relevance, such as a conversation about a request that was never revealed, are kept for the same period on a second ground: customers and suppliers deal with QuotesDone in the course of their business, and a claim between merchants about their commercial obligations may be brought within five years from the date the obligation falls due (Article 92 of the Commercial Transactions Law, Federal Decree-Law No. 50 of 2022). Keeping the record for that period allows a claim to be established or defended, which Article 4 of the PDPL permits. Our periods follow both:</p><ul><li>Account data: while your account is active, and for five years after its last activity.</li><li>Conversations with us (emails, WhatsApp messages, and portal and website chat): while your account is active, and for five years after its last activity, and in any case for five years from the end of the calendar year in which the message was written. The message text and its archived copy are then deleted.</li><li>Requests and their records (request details, drawings, bills of quantities, photographs, quotes and comparison reports): for at least five years from the end of the calendar year in which they were created.</li><li>Transaction and financial records, including Reveal Fee records: for at least five years from the end of the calendar year in which they were created, or longer where the law requires.</li><li>Supplier KYC documents: for the duration of the relationship and five years after it ends.</li><li>Records connected with an open dispute, refund, complaint or unpaid amount: until the matter is closed, even where a period above has ended.</li><li>An unfinished sign-up (an account whose email, mobile verification or acceptance of the terms was not completed within 30 minutes): deleted in full after 30 minutes, with nothing sent to it.</li><li>Backup copies of our database: 30 days of daily copies and one copy for each of the last 12 months.</li><li>Security and audit logs: for limited periods.</li></ul><p>When a retention period ends, we securely delete or irreversibly anonymise the data.</p><h2>8. Your Rights Under the PDPL</h2><p>Subject to the conditions and exceptions in the PDPL, you have the right to:</p><ul><li>Access your personal data and obtain information about how it is processed.</li><li>Request correction of inaccurate or incomplete data.</li><li>Request deletion of your data where the legal grounds apply.</li><li>Object to, or request restriction of, certain processing, including certain automated processing, within the limits of Article 18 of the PDPL (section 4).</li><li>Request that your personal data be provided to you, or transferred to another controller, in a structured, commonly used, machine-readable format (data portability), where technically feasible.</li><li>Withdraw consent at any time, without affecting processing carried out before withdrawal.</li></ul><p>To exercise any right, contact us at management@quotesdone.com. We will respond within the timeframes required by the PDPL. If you are not satisfied, you may lodge a complaint with the UAE Data Office.</p><h2>9. Electronic Marketing and Communications</h2><p>We send transactional messages you need to use the service — for example mobile one-time passwords (OTP), request and quote notifications, and account or payment confirmations — on the basis of our contract with you; these are not marketing.</p><p>We send marketing or promotional messages by email, SMS, WhatsApp or other electronic means only if you have ticked the separate box to agree to them. The box is never ticked in advance, it is not needed to use the service, and we record when you ticked it. You can withdraw consent or unsubscribe at any time using the link or instructions in the message, or by emailing management@quotesdone.com.</p><p><strong>Invitations to businesses.</strong> We invite businesses in the UAE to list as suppliers on QuotesDone. For this we use business contact details that the business itself has published, for example on its website or in a public business directory: the company name, its trade, and its published business email address. We rely on Article 4 of the PDPL, which permits the processing of data that has become available and known to all by an act of its owner: the business published this address itself. We send one invitation and up to three reminders, by email, during working hours. Every message identifies QuotesDone and contains a one-click unsubscribe link, and an unsubscribe stops every further message at once and permanently. We measure whether these emails are opened: some carry a tiny image served from our own website, and when it loads we record the time, the description the email program sends and a one-way coded form of the network address, never the address itself. We use this data for nothing else and we do not sell it. You may ask us at any time what we hold and where we obtained it, or ask us to delete it; we then keep only the record of your opt-out, so that we do not contact you again.</p><p>We handle electronic communications in line with the UAE telecommunications and electronic-marketing rules overseen by the Telecommunications and Digital Government Regulatory Authority (TDRA) and the Electronic Transactions and Trust Services Law (Federal Decree-Law No. 46 of 2021). We do not sell your contact details for third-party marketing.</p><h2>10. Security</h2><p>We apply appropriate technical and organisational measures to protect personal data against unauthorised access, loss, alteration or disclosure, consistent with the PDPL and the Electronic Transactions and Trust Services Law, Federal Decree-Law No. 46 of 2021.</p><ul><li>Access to personal data is restricted to authorised personnel on a need-to-know basis.</li><li>We use encryption in transit, OTP verification for customer mobile numbers, and segregation of anonymised request content from identity data.</li><li>Payment card data is handled by Stripe, our PCI DSS–certified payment processor, and is not stored by us.</li></ul><p>No system can be guaranteed to be completely secure. If a personal data breach occurs that meets the legal threshold, we will notify the UAE Data Office and affected individuals as required by the PDPL.</p><h2>11. Children, Changes and Contact</h2><p>QuotesDone is a business-to-business platform intended for users aged 18 and over. It is not directed at minors, and we do not knowingly collect personal data from children. If you believe a minor has provided us data, please contact us so we can delete it.</p><p>We may update this Privacy Policy from time to time to reflect changes in our services or the law. The current version is always available on our platform, and material changes will be notified where appropriate.</p><p>For any privacy question, to exercise your rights, or to reach our data protection contact, please use:</p><ul><li>Email: management@quotesdone.com</li><li>Phone: +971 56 791 8605</li><li>WhatsApp: +1 218 316 6814</li><li>Post: QuotesDone Technologies, Dubai, United Arab Emirates (our DET Trader License is for an online business with no shop front, so there is no street address)</li></ul><p>This policy is governed by the laws of the UAE, and disputes are subject to the courts of Dubai.</p></div>$qd_privacy$, version = '1.9', effective_date = date '2026-11-03',
       content_sha256 = '077952bce6863e9abea3e932924e7039a250be53d11ab8f2224efa9d2aac8f9c', updated_at = now()
 where slug = 'privacy' and version = '1.8';

-- verdict
select case when
       (select count(*) from public.legal_documents a where a.slug = 'privacy-v1.8' and a.category = 'archived'
          and a.content_sha256 = 'b16a707f2ede426ca37ac7f87136b314a17c674f17a8ac6614ec26b1fe93e5e9'
          and encode(sha256(convert_to(a.body_html, 'UTF8')), 'hex') = a.content_sha256) = 1
   and (select count(*) from public.legal_documents d where d.slug = 'privacy' and d.version = '1.9' and d.content_sha256 = '077952bce6863e9abea3e932924e7039a250be53d11ab8f2224efa9d2aac8f9c'
          and encode(sha256(convert_to(d.body_html, 'UTF8')), 'hex') = d.content_sha256
          and d.body_html like '%We measure whether these emails are opened%' and d.body_html !~* 'mAIM') = 1
  then 'PROBE OK' else 'PROBE FAILED: privacy 1.8 is not archived byte for byte, or the live privacy row is not the 1.9 text' end as verdict;
